(()=>{chrome.runtime.onInstalled.addListener(()=>{chrome.contextMenus.create({id:"spashto-simplify",title:"Simplify this",contexts:["selection"]}),chrome.sidePanel.setPanelBehavior({openPanelOnActionClick:!0}).catch(console.error)});chrome.contextMenus.onClicked.addListener((e,t)=>{e.menuItemId==="spashto-simplify"&&e.selectionText&&chrome.storage.local.set({spashto_selected_text:e.selectionText},()=>{t?.windowId&&chrome.sidePanel.open({windowId:t.windowId})})});})();
